        Surah(56, "الواقعة", "Al-Waqi'ah", "The Inevitable", 96, "Meccan", 27, "إِذَا وَقَعَتِ الْوَاقِعَةُ ۝ لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ ۝ خَافِضَةٌ رَّافِعَةٌ", "When the Occurrence occurs, there is, at its occurrence, no denial. It will bring down [some] and raise up [others]."),
        Surah(57, "الحديد", "Al-Hadid", "The Iron", 29, "Medinan", 27, "سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ ۖ وَهُوَ الْعَزِيزُ الْحَكِيمُ", "Whatever is in the heavens and earth exalts Allah, and He is the Exalted in Might, the Wise."),
        Surah(58, "المجادلة", "Al-Mujadila", "The Pleading Woman", 22, "Medinan", 28, "قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللَّهِ", "Certainly has Allah heard the speech of the one who argues with you, [O Muhammad], concerning her husband and directs her complaint to Allah."),
        Surah(59, "الحشر", "Al-Hashr", "The Exile", 24, "Medinan", 28, "سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۖ وَهُوَ الْعَزِيزُ الْحَكِيمُ", "Whatever is in the heavens and whatever is on the earth is exalting Allah, and He is the Exalted in Might, the Wise."),
        Surah(60, "الممتحنة", "Al-Mumtahanah", "She that is to be examined", 13, "Medinan", 28, "يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا عَدُوِّي وَعَدُوَّكُمْ أَوْلِيَاءَ", "O you who have believed, do not take My enemies and your enemies as allies."),
        Surah(61, "الصف", "As-Saff", "The Ranks", 14, "Medinan", 28, "سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۖ وَهُوَ الْعَزِيزُ الْحَكِيمُ", "Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise."),
        Surah(62, "الجمعة", "Al-Jumu'ah", "Friday", 11, "Medinan", 28, "يُسَبِّحُ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ الْمَلِكِ الْقُدُّوسِ الْعَزِيزِ الْحَكِيمِ", "Whatever is in the heavens and whatever is on the earth is exalting Allah, the Sovereign, the Pure, the Exalted in Might, the Wise."),
        Surah(63, "المنافقون", "Al-Munafiqun", "The Hypocrites", 11, "Medinan", 28, "إِذَا جَاءَكَ الْمُنَافِقُونَ قَالُوا نَشْهَدُ إِنَّكَ لَرَسُولُ اللَّهِ", "When the hypocrites come to you, they say, 'We testify that you are the Messenger of Allah.'"),
        Surah(64, "التغابن", "At-Taghabun", "Mutual Disillusion", 18, "Medinan", 28, "يُسَبِّحُ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۖ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ", "Whatever is in the heavens and whatever is on the earth is exalting Allah. To Him belongs dominion, and to Him belongs [all] praise."),
        Surah(65, "الطلاق", "At-Talaq", "The Divorce", 12, "Medinan", 28, "يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ", "O Prophet, when you [Muslims] divorce women, divorce them for [the commencement of] their waiting period."),
        Surah(66, "التحريم", "At-Tahrim", "The Prohibition", 12, "Medinan", 28, "يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ", "O Prophet, why do you prohibit [yourself from] what Allah has made lawful for you?"),
        Surah(67, "الملك", "Al-Mulk", "The Sovereignty", 30, "Meccan", 29, "تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ", "Blessed is He in whose hand is dominion, and He is over all things competent."),
        Surah(68, "القلم", "Al-Qalam", "The Pen", 52, "Meccan", 29, "ن ۚ وَالْقَلَمِ وَمَا يَسْطُرُونَ ۝ مَا أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍ", "Nun. By the pen and what they inscribe, you are not, [O Muhammad], by the favor of your Lord, a madman."),
        Surah(69, "الحاقة", "Al-Haqqah", "The Inevitable Reality", 52, "Meccan", 29, "الْحَاقَّةُ ۝ مَا الْحَاقَّةُ ۝ وَمَا أَدْرَاكَ مَا الْحَاقَّةُ", "The Inevitable Reality - What is the Inevitable Reality? And what can make you know what is the Inevitable Reality?"),
        Surah(70, "المعارج", "Al-Ma'arij", "The Ascending Stairways", 44, "Meccan", 29, "سَأَلَ سَائِلٌ بِعَذَابٍ وَاقِعٍ ۝ لِّلْكَافِرِينَ لَيْسَ لَهُ دَافِعٌ", "A questioner asked about a penalty bound to happen to the disbelievers; of it there is no preventer."),
        Surah(71, "نوح", "Nuh", "Noah", 28, "Meccan", 29, "إِنَّا أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ", "Indeed, We sent Noah to his people, [saying], 'Warn your people before there comes to them a painful punishment.'"),
        Surah(72, "الجن", "Al-Jinn", "The Jinn", 28, "Meccan", 29, "قُلْ أُوحِيَ إِلَيَّ أَنَّهُ اسْتَمَعَ نَفَرٌ مِّنَ الْجِنِّ فَقَالُوا إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا", "Say, [O Muhammad], 'It has been revealed to me that a group of the jinn listened and said, Indeed, we have heard an amazing Qur'an.'"),
        Surah(73, "المزمل", "Al-Muzzammil", "The Enshrouded One", 20, "Meccan", 29, "يَا أَيُّهَا الْمُزَّمِّلُ ۝ قُمِ اللَّيْلَ إِلَّا قَلِيلًا ۝ نِّصْفَهُ أَوِ انقُصْ مِنْهُ قَلِيلًا", "O you who wraps himself [in clothing], arise [to pray] the night, except for a little - half of it - or lessen it a little."),
        Surah(74, "المدثر", "Al-Muddaththir", "The Cloaked One", 56, "Meccan", 29, "يَا أَيُّهَا الْمُدَّثِّرُ ۝ قُمْ فَأَنذِرْ ۝ وَرَبَّكَ فَكَبِّرْ", "O you who covers himself [with a garment], arise and warn, and your Lord magnify."),
        Surah(75, "القيامة", "Al-Qiyamah", "The Resurrection", 40, "Meccan", 29, "لَا أُقْسِمُ بِيَوْمِ الْقِيَامَةِ ۝ وَلَا أُقْسِمُ بِالنَّفْسِ اللَّوَّامَةِ", "I swear by the Day of Resurrection, and I swear by the reproaching soul."),
        Surah(76, "الإنسان", "Al-Insan", "Man", 31, "Medinan", 29, "هَلْ أَتَىٰ عَلَى الْإِنسَانِ حِينٌ مِّنَ الدَّهْرِ لَمْ يَكُن شَيْئًا مَّذْكُورًا", "Has there [not] come upon man a period of time when he was not a thing [even] mentioned?"),
        Surah(77, "المرسلات", "Al-Mursalat", "The Emissaries", 50, "Meccan", 29, "وَالْمُرْسَلَاتِ عُرْفًا ۝ فَالْعَاصِفَاتِ عَصْفًا", "By those [winds] sent forth in gusts, and the winds that blow violently..."),
        Surah(78, "النبأ", "An-Naba", "The Tidings", 40, "Meccan", 30, "عَمَّ يَتَسَاءَلُونَ ۝ عَنِ النَّبَإِ الْعَظِيمِ", "About what are they asking one another? About the great news."),
        Surah(79, "النازعات", "An-Nazi'at", "Those who drag forth", 46, "Meccan", 30, "وَالنَّازِعَاتِ غَرْقًا ۝ وَالنَّاشِطَاتِ نَشْطًا", "By those [angels] who extract with violence, and those who remove with ease..."),
        Surah(80, "عبس", "Abasa", "He Frowned", 42, "Meccan", 30, "عَبَسَ وَتَوَلَّىٰ ۝ أَن جَاءَهُ الْأَعْمَىٰ", "The Prophet frowned and turned away because there came to him the blind man."),
        Surah(81, "التكوير", "At-Takwir", "The Overthrowing", 29, "Meccan", 30, "إِذَا الشَّمْسُ كُوِّرَتْ ۝ وَإِذَا النُّجُومُ انكَدَرَتْ", "When the sun is wrapped up [in darkness], and when the stars fall, dispersing."),
        Surah(82, "الانفطار", "Al-Infitar", "The Cleaving", 19, "Meccan", 30, "إِذَا السَّمَاءُ انفَطَرَتْ ۝ وَإِذَا الْكَوَاكِبُ انتَثَرَتْ", "When the sky breaks apart, and when the stars are scattered."),
        Surah(83, "المطففين", "Al-Mutaffifin", "Defrauding", 36, "Meccan", 30, "وَيْلٌ لِّلْمُطَفِّفِينَ ۝ الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ", "Woe to those who give less [than due], who, when they take a measure from people, take in full."),
        Surah(84, "الانشقاق", "Al-Inshiqaq", "The Splitting Open", 25, "Meccan", 30, "إِذَا السَّمَاءُ انشَقَّتْ ۝ وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ", "When the sky has split open, and has listened to its Lord and was obligated [to do so]."),
        Surah(85, "البروج", "Al-Buruj", "The Constellations", 22, "Meccan", 30, "وَالسَّمَاءِ ذَاتِ الْبُرُوجِ ۝ وَالْيَوْمِ الْمَوْعُودِ", "By the sky containing great stars, and [by] the promised Day."),
        Surah(86, "الطارق", "At-Tariq", "The Nightcomer", 17, "Meccan", 30, "وَالسَّمَاءِ وَالطَّارِقِ ۝ وَمَا أَدْرَاكَ مَا الطَّارِقُ ۝ النَّجْمُ الثَّاقِبُ", "By the sky and the night comer - And what can make you know what is the night comer? It is the piercing star."),
        Surah(87, "الأعلى", "Al-A'la", "The Most High", 19, "Meccan", 30, "سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ۝ الَّذِي خَلَقَ فَسَوَّىٰ", "Exalt the name of your Lord, the Most High, who created and proportioned."),
        Surah(88, "الغاشية", "Al-Ghashiyah", "The Overwhelming Event", 26, "Meccan", 30, "هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ۝ وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ", "Has there reached you the report of the Overwhelming [event]? [Some] faces, that Day, will be humbled."),
        Surah(89, "الفجر", "Al-Fajr", "The Dawn", 30, "Meccan", 30, "وَالْفَجْرِ ۝ وَلَيَالٍ عَشْرٍ ۝ وَالشَّفْعِ وَالْوَتْرِ", "By the dawn, and [by] ten nights, and [by] the even and the odd..."),
        Surah(90, "البلد", "Al-Balad", "The City", 20, "Meccan", 30, "لَا أُقْسِمُ بِهَٰذَا الْبَلَدِ ۝ وَأَنتَ حِلٌّ بِهَٰذَا الْبَلَدِ", "I swear by this city [Makkah] - and you, [O Muhammad], are free of restriction in this city."),
        Surah(91, "الشمس", "Ash-Shams", "The Sun", 15, "Meccan", 30, "وَالشَّمْسِ وَضُحَاهَا ۝ وَالْقَمَرِ إِذَا تَلَاهَا ۝ وَالنَّهَارِ إِذَا جَلَّاهَا", "By the sun and its brightness, and [by] the moon when it follows it, and [by] the day when it displays it."),
        Surah(92, "الليل", "Al-Layl", "The Night", 21, "Meccan", 30, "وَاللَّيْلِ إِذَا يَغْشَىٰ ۝ وَالنَّهَارِ إِذَا تَجَلَّىٰ", "By the night when it covers, and [by] the day when it appears..."),
        Surah(93, "الضحى", "Ad-Duha", "The Morning Hours", 11, "Meccan", 30, "وَالضُّحَىٰ ۝ وَاللَّيْلِ إِذَا سَجَىٰ ۝ مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ", "By the morning sunlight, and [by] the night when it grows still, your Lord has not forsaken you, nor has He detested [you]."),
        Surah(94, "الشرح", "Ash-Sharh", "The Relief", 8, "Meccan", 30, "أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ ۝ وَوَضَعْنَا عَنكَ وِزْرَكَ ۝ الَّذِي أَنقَضَ ظَهْرَكَ", "Did We not expand for you, [O Muhammad], your breast? And We removed from you your burden which weighed upon your back."),
        Surah(95, "التين", "At-Tin", "The Fig", 8, "Meccan", 30, "وَالتِّينِ وَالزَّيْتُونِ ۝ وَطُورِ سِينِينَ ۝ وَهَٰذَا الْبَلَدِ الْأَمِينِ", "By the fig and the olive, and [by] Mount Sinai, and [by] this secure city [Makkah]!"),
        Surah(96, "العلق", "Al-'Alaq", "The Clot", 19, "Meccan", 30, "اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ ۝ خَلَقَ الْإِنسَانَ مِنْ عَلَقٍ ۝ اقْرَأْ وَرَبُّكَ الْأَكْرَمُ", "Recite in the name of your Lord who created - created man from a clinging substance. Recite, and your Lord is the most Generous."),
        Surah(97, "القدر", "Al-Qadr", "The Night of Decree", 5, "Meccan", 30, "إِنَّا أَنزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ ۝ وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ ۝ لَيْلَةُ الْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ", "Indeed, We sent the Qur'an down during the Night of Decree. And what can make you know what is the Night of Decree? The Night of Decree is better than a thousand months."),
        Surah(98, "البينة", "Al-Bayyinah", "The Clear Proof", 8, "Medinan", 30, "لَمْ يَكُنِ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ الْبَيِّنَةُ", "Those who disbelieved among the People of the Scripture and the polytheists were not to be parted [from misbelief] until there came to them clear evidence."),
        Surah(99, "الزلزلة", "Az-Zalzalah", "The Earthquake", 8, "Medinan", 30, "إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا ۝ وَأَخْرَجَتِ الْأَرْضُ أَثْقَالَهَا", "When the earth is shaken with its [final] earthquake, and the earth discharges its burdens."),
        Surah(100, "العاديات", "Al-'Adiyat", "The Courser", 11, "Meccan", 30, "وَالْعَادِيَاتِ ضَبْحًا ۝ فَالْمُورِيَاتِ قَدْحًا ۝ فَالْمُغِيرَاتِ صُبْحًا", "By the racers, panting, and the producers of sparks [when] striking, and the chargers at dawn..."),
        Surah(101, "القارعة", "Al-Qari'ah", "The Calamity", 11, "Meccan", 30, "الْقَارِعَةُ ۝ مَا الْقَارِعَةُ ۝ وَمَا أَدْرَاكَ مَا الْقَارِعَةُ", "The Striking Calamity - What is the Striking Calamity? And what can make you know what is the Striking Calamity?"),
        Surah(102, "التكاثر", "At-Takathur", "The Rivalry in World Increase", 8, "Meccan", 30, "أَلْهَاكُمُ التَّكَاثُرُ ۝ حَتَّىٰ زُرْتُمُ الْمَقَابِرَ", "Competition in [world] increase diverts you, until you visit the graveyards."),
        Surah(103, "العصر", "Al-'Asr", "The Declining Day", 3, "Meccan", 30, "وَالْعَصْرِ ۝ إِنَّ الْإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ", "By time, indeed, mankind is in loss, except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience."),
        Surah(104, "الهمزة", "Al-Humazah", "The Traducer", 9, "Meccan", 30, "وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ ۝ الَّذِي جَمَعَ مَالًا وَعَدَّدَهُ", "Woe to every scorner and mocker, who collects wealth and [continuously] counts it."),
        Surah(105, "الفيل", "Al-Fil", "The Elephant", 5, "Meccan", 30, "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ", "Have you not considered, [O Muhammad], how your Lord dealt with the companions of the elephant?"),
        Surah(106, "قريش", "Quraysh", "Quraysh", 4, "Meccan", 30, "لِإِيلَافِ قُرَيْشٍ ۝ إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ", "For the accustomed security of the Quraysh - their accustomed security in the caravan of winter and summer..."),
        Surah(107, "الماعون", "Al-Ma'un", "The Small Kindnesses", 7, "Meccan", 30, "أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ ۝ فَذَٰلِكَ الَّذِي يَدُعُّ الْيَتِيمَ", "Have you seen the one who denies the Recompense? For that is the one who drives away the orphan."),
        Surah(108, "الكوثر", "Al-Kawthar", "The Abundance", 3, "Meccan", 30, "إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ ۝ إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ", "Indeed, We have granted you, [O Muhammad], al-Kawthar. So pray to your Lord and sacrifice. Indeed, your enemy is the one cut off."),
        Surah(109, "الكافرون", "Al-Kafirun", "The Disbelievers", 6, "Meccan", 30, "قُلْ يَا أَيُّهَا الْكَافِرُونَ ۝ لَا أَعْبُدُ مَا تَعْبُدُونَ ۝ وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ", "Say, 'O disbelievers, I do not worship what you worship. Nor are you worshippers of what I worship.'"),
        Surah(110, "النصر", "An-Nasr", "The Divine Support", 3, "Medinan", 30, "إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ۝ وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا", "When the victory of Allah has come and the conquest, and you see the people entering into the religion of Allah in multitudes..."),
        Surah(111, "المسد", "Al-Masad", "The Palm Fiber", 5, "Meccan", 30, "تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ ۝ مَا أَغْنَىٰ عَنْهُ مَالُهُ وَمَا كَسَبَ", "May the hands of Abu Lahab be ruined, and ruined is he. His wealth will not avail him or that which he gained."),
        Surah(112, "الإخلاص", "Al-Ikhlas", "The Sincerity", 4, "Meccan", 30, "قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ", "Say, 'He is Allah, [who is] One, Allah, the Eternal Refuge. He neither begets nor is born, Nor is there to Him any equivalent.'"),
        Surah(113, "الفلق", "Al-Falaq", "The Daybreak", 5, "Meccan", 30, "قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِن شَرِّ مَا خَلَقَ ۝ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ", "Say, 'I seek refuge in the Lord of daybreak from the evil of that which He created, and from the evil of darkness when it settles...'"),
        Surah(114, "الناس", "An-Nas", "Mankind", 6, "Meccan", 30, "قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَٰهِ النَّاسِ ۝ مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ", "Say, 'I seek refuge in the Lord of mankind, the Sovereign of mankind, the God of mankind, from the evil of the retreating whisperer...'")
    )
}
